CREATE TABLE rm_group_manifest_events (
 id INTEGER PRIMARY KEY CHECK(id > 0),
 manifest_hash TEXT NOT NULL UNIQUE CHECK(length(manifest_hash)=64 AND manifest_hash NOT GLOB '*[^0-9a-f]*'),
 previous_hash TEXT CHECK(previous_hash IS NULL OR (length(previous_hash)=64 AND previous_hash NOT GLOB '*[^0-9a-f]*')),
 canonical_manifest TEXT NOT NULL CHECK(length(canonical_manifest) BETWEEN 2 AND 262144),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 19 AND 30)
);
CREATE TRIGGER rm_group_manifest_events_no_update BEFORE UPDATE ON rm_group_manifest_events BEGIN SELECT RAISE(ABORT, 'group manifest events are append-only'); END;
CREATE TRIGGER rm_group_manifest_events_no_delete BEFORE DELETE ON rm_group_manifest_events BEGIN SELECT RAISE(ABORT, 'group manifest events are append-only'); END;
